            d1.setOverrideDimensionName("Promotion Media");
            d1.setForeignKey(org.eclipse.daanse.rolap.mapping.instance.emf.complex.foodmart.CatalogSupplier.COLUMN_PROMOTION_ID_SALESFACT);
            d1.setDimension(dimension);

