            level3.setUniqueMembers(false);

            level4.setName("Product Subcategory");
            level4.setColumn((Column) copier.get(CatalogSupplier.COLUMN_PRODUCT_SUBCATEGORY_PRODUCT_CLASS));
            level4.setUniqueMembers(false);

